<script setup>
import {reactive,ref,onMounted} from 'vue';import {UserRound,ShieldCheck} from 'lucide-vue-next';import {api,session} from '../lib/api';import {notify} from '../lib/ui';import StatePanel from '../components/StatePanel.vue';
const form=reactive({first_name:'',last_name:'',phone:'',address:'',province:'',postal_code:''}),loading=ref(true),error=ref(''),saving=ref(false);
async function load(){loading.value=true;error.value='';try{const {data}=await api('/me/profile');for(const k of Object.keys(form))form[k]=data[k]||'';}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function save(){saving.value=true;try{await api('/me/profile',{method:'PATCH',body:{...form}});notify('บันทึกข้อมูลส่วนตัวแล้ว');}catch(e){notify(e.message,'error');}finally{saving.value=false;}}
onMounted(load);
</script>
<template><section class="container section"><div class="page-heading"><div><p class="eyebrow">YOUR ACCOUNT</p><h1>ข้อมูลส่วนตัว</h1><p class="muted">เตรียมข้อมูลให้พร้อมสำหรับการเข้าพักครั้งต่อไป</p></div></div><StatePanel :loading="loading" :error="error" @retry="load"/><div v-if="!loading&&!error" class="profile-layout"><aside class="panel account-card"><div class="avatar large"><UserRound :size="30"/></div><h2>{{ session.user.username }}</h2><p class="muted">{{ session.user.email }}</p><span class="badge active"><ShieldCheck :size="14"/> สมาชิกโรงแรม</span><RouterLink to="/my-bookings" class="btn outline full">ดูการจองของฉัน</RouterLink></aside><form class="panel" @submit.prevent="save"><h2>ข้อมูลผู้เข้าพัก</h2><div class="form-grid"><label>ชื่อ<input v-model="form.first_name" autocomplete="given-name" maxlength="100" required/></label><label>นามสกุล<input v-model="form.last_name" autocomplete="family-name" maxlength="100" required/></label></div><label>เบอร์โทรศัพท์<input v-model="form.phone" type="tel" autocomplete="tel" maxlength="20" required/></label><label>ที่อยู่<textarea v-model="form.address" autocomplete="street-address" rows="3" maxlength="5000"/></label><div class="form-grid"><label>จังหวัด<input v-model="form.province" autocomplete="address-level1" maxlength="100"/></label><label>รหัสไปรษณีย์<input v-model="form.postal_code" autocomplete="postal-code" maxlength="10"/></label></div><div class="modal-actions"><button class="btn primary" :disabled="saving">{{ saving?'กำลังบันทึก…':'บันทึกข้อมูล' }}</button></div></form></div></section></template>
